(56, 3, 6, 'Bài 6 (Mẫu 26-30)', 'Ngữ pháp N3 - Mẫu 26-30', 6, TRUE, 1),
(57, 3, 7, 'Bài 7 (Mẫu 31-35)', 'Ngữ pháp N3 - Mẫu 31-35', 7, TRUE, 1),
